begin;
create table public.routing_safety_records(user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,route_record_id text not null check(route_record_id~'^dlr_[a-f0-9]{24}$'),record_hash text not null check(record_hash~'^[a-f0-9]{64}$'),decision text not null check(decision in('allow','block')),provider text not null default '' check(char_length(provider)<=120),cross_check_status text not null default 'unavailable' check(char_length(cross_check_status)<=40),safety_record jsonb not null check(jsonb_typeof(safety_record)='object' and octet_length(safety_record::text)<=262144),created_at timestamptz not null,expires_at timestamptz not null,uploaded_at timestamptz not null default now(),primary key(user_id,route_record_id),unique(user_id,record_hash),check(expires_at>created_at));
create table public.routing_incidents(user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,client_incident_id uuid not null,route_record_id text not null,event_type text not null check(event_type~'^[a-z0-9-]{1,80}$'),occurred_at timestamptz not null,event_data jsonb not null default '{}'::jsonb check(jsonb_typeof(event_data)='object' and octet_length(event_data::text)<=8192),uploaded_at timestamptz not null default now(),primary key(user_id,client_incident_id),foreign key(user_id,route_record_id) references public.routing_safety_records(user_id,route_record_id) on delete cascade);
create table public.routing_route_invalidations(id uuid primary key default gen_random_uuid(),record_hash text check(record_hash is null or record_hash~'^[a-f0-9]{64}$'),scope_type text not null check(scope_type in('record','provider','state','global')),scope_value text not null default '' check(char_length(scope_value)<=120),reason text not null check(char_length(reason) between 10 and 1000),active boolean not null default true,starts_at timestamptz not null default now(),expires_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(expires_at is null or expires_at>starts_at));
create index routing_safety_records_expiry_idx on public.routing_safety_records(expires_at);create index routing_incidents_route_time_idx on public.routing_incidents(user_id,route_record_id,occurred_at);create index routing_route_invalidations_active_idx on public.routing_route_invalidations(active,scope_type,scope_value) where active;
alter table public.routing_safety_records enable row level security;alter table public.routing_incidents enable row level security;alter table public.routing_route_invalidations enable row level security;
revoke all on public.routing_safety_records from anon,authenticated;revoke all on public.routing_incidents from anon,authenticated;revoke all on public.routing_route_invalidations from anon,authenticated;grant select,insert,delete on public.routing_safety_records to authenticated;grant select,insert,delete on public.routing_incidents to authenticated;
create policy routing_safety_records_select_own on public.routing_safety_records for select to authenticated using(user_id=auth.uid());create policy routing_safety_records_insert_own on public.routing_safety_records for insert to authenticated with check(user_id=auth.uid());create policy routing_safety_records_delete_own on public.routing_safety_records for delete to authenticated using(user_id=auth.uid());create policy routing_incidents_select_own on public.routing_incidents for select to authenticated using(user_id=auth.uid());create policy routing_incidents_insert_own on public.routing_incidents for insert to authenticated with check(user_id=auth.uid());create policy routing_incidents_delete_own on public.routing_incidents for delete to authenticated using(user_id=auth.uid());
comment on table public.routing_safety_records is 'Private immutable route-decision evidence. Raw address labels and permit documents are prohibited.';comment on table public.routing_incidents is 'Private bounded incident replay data uploaded only after explicit user opt-in.';comment on table public.routing_route_invalidations is 'Service/admin-only safety invalidations.';
commit;
